<?php
$title='Appointments';$subtitle='Meetings booked by leads or your team';
if(is_post()){
  $a=$_POST['a']??'';
  try{
    if($a==='add'){
      $t=strtotime($_POST['at']??'');if(!$t)throw new Exception('Pick a date and time.');
      $lid=(int)($_POST['lead']??0);
      if(!$lid){$n=trim($_POST['name']??'');if($n==='')throw new Exception('Choose a lead or enter a name.');$lid=CRM::create(['contact_name'=>$n,'name'=>$n,'phone'=>trim($_POST['phone']??''),'email'=>trim($_POST['email']??'')],'manual','Appointment');}
      Booking::book($lid,$t,'admin',trim($_POST['notes']??''),trim($_POST['title']??'')?:null);flash('Appointment booked.');}
    if($a==='st'){$ap=DB::row('SELECT * FROM appointments WHERE id=?',[(int)$_POST['id']]);if($ap){DB::update('appointments',['status'=>$_POST['st']],'id=?',[$ap['id']]);event($ap['lead_id'],'note','Appointment marked '.str_replace('_',' ',$_POST['st']));}}
  }catch(Throwable $e){flash(e($e->getMessage()),'err');}
  back(url('appointments'));}
$m=preg_match('/^\d{4}-\d{2}$/',$_GET['m']??'')?$_GET['m']:date('Y-m');
$first=strtotime($m.'-01');$start=strtotime('monday this week',$first);if(date('N',$first)==1)$start=$first;
$end=strtotime('+41 days',$start);
$rows=DB::all('SELECT a.*,l.name,l.contact_name FROM appointments a LEFT JOIN leads l ON l.id=a.lead_id WHERE a.start_at BETWEEN ? AND ? ORDER BY a.start_at',[date('Y-m-d 00:00:00',$start),date('Y-m-d 23:59:59',$end)]);
$by=[];foreach($rows as $r)$by[substr($r['start_at'],0,10)][]=$r;
$up=DB::all("SELECT a.*,l.name,l.contact_name,l.phone FROM appointments a LEFT JOIN leads l ON l.id=a.lead_id WHERE a.status='scheduled' AND a.start_at>=NOW()-INTERVAL 1 HOUR ORDER BY a.start_at LIMIT 12");
$leads=DB::all('SELECT id,name,contact_name FROM leads WHERE is_lead=1 ORDER BY COALESCE(lead_at,created_at) DESC LIMIT 300');
$k=DB::row("SELECT SUM(status='scheduled' AND start_at>=NOW()) up,SUM(DATE(start_at)=CURDATE() AND status='scheduled') td,SUM(status='completed') dn,SUM(status='no_show') ns FROM appointments");
?>
<div class="kpis"><div class="kpi"><span class="hi hi-t"><?=icon('cal')?></span><div><span>Upcoming</span><b><?=(int)$k['up']?></b><small><?=(int)$k['td']?> today</small></div></div><div class="kpi"><span class="hi hi-g"><?=icon('check')?></span><div><span>Completed</span><b><?=(int)$k['dn']?></b><small>meetings held</small></div></div><div class="kpi"><span class="hi hi-o"><?=icon('alert')?></span><div><span>No-shows</span><b><?=(int)$k['ns']?></b><small>follow up again</small></div></div><div class="kpi kpi-n"><span class="hi hi-y"><?=icon('link')?></span><div><span>Public booking link</span><b style="font-size:15px;margin-top:6px"><a class="lnk" style="color:var(--y)" href="#" data-copy="<?=e(Booking::link())?>">Copy link</a></b><small><a href="<?=e(Booking::link())?>" target="_blank" style="color:#9FB0CC">Preview page ↗</a></small></div></div></div>
<div class="g3"><div class="col"><div class="card"><div class="card-h"><h3><span class="hi hi-t"><?=icon('clock')?></span>Next up</h3><button class="btn btn-y btn-sm" onclick="A.modal('m-add')"><?=icon('plus')?>New</button></div><?php if(!$up):?><div class="empty sm"><?=icon('cal')?><p>No upcoming appointments.</p></div><?php endif?><?php foreach($up as $a):?><div class="msg"><div class="msg-h"><?=icon('cal')?><b><?=e(date('D, d M · h:i A',strtotime($a['start_at'])))?></b></div><p><a class="lnk" href="<?=url('lead',['id'=>$a['lead_id']])?>"><?=e($a['contact_name']?:$a['name'])?></a> · <?=e($a['title'])?><?=$a['phone']?'<br>'.e($a['phone']):''?></p><form method="post" class="row mt" style="gap:4px"><?=csrf_field()?><input type="hidden" name="a" value="st"><input type="hidden" name="id" value="<?=$a['id']?>"><button class="btn btn-xs" name="st" value="completed">Done</button><button class="btn btn-xs" name="st" value="no_show">No-show</button><button class="btn btn-xs" name="st" value="cancelled">Cancel</button></form></div><?php endforeach?><p class="hint">Working hours, slot length and reminders: <a class="lnk" href="<?=url('settings',['tab'=>'appointments'])?>">Settings → Appointments</a></p></div></div>
<div class="col"><div class="card"><div class="card-h"><h3><?=e(date('F Y',$first))?></h3><div class="row"><a class="btn btn-sm" href="<?=url('appointments',['m'=>date('Y-m',strtotime('-1 month',$first))])?>">‹</a><a class="btn btn-sm" href="<?=url('appointments')?>">Today</a><a class="btn btn-sm" href="<?=url('appointments',['m'=>date('Y-m',strtotime('+1 month',$first))])?>">›</a></div></div><div class="cal"><?php foreach(['Mon','Tue','Wed','Thu','Fri','Sat','Sun'] as $dn):?><div class="ch"><?=$dn?></div><?php endforeach?><?php for($d=$start;$d<=$end;$d=strtotime('+1 day',$d)):$ds=date('Y-m-d',$d);?><div class="<?=date('Y-m',$d)!==$m?'out':''?> <?=$ds===date('Y-m-d')?'td':''?>"><span class="dn"><?=date('j',$d)?></span><?php foreach($by[$ds]??[] as $a):?><a class="ev <?=$a['status']==='completed'?'done':(in_array($a['status'],['cancelled','no_show'],true)?'cx':'')?>" href="<?=url('lead',['id'=>$a['lead_id']])?>" title="<?=e($a['title'])?>"><?=date('H:i',strtotime($a['start_at']))?> <?=e($a['contact_name']?:$a['name'])?></a><?php endforeach?></div><?php endfor?></div></div></div></div>
<div class="md" id="m-add"><form class="md-b" method="post"><?=csrf_field()?><input type="hidden" name="a" value="add"><div class="md-h"><h3><span class="hi hi-t"><?=icon('cal')?></span>New appointment</h3><button type="button" class="ib" onclick="A.close()"><?=icon('x')?></button></div><label>Lead<select name="lead"><option value="">— New person —</option><?php foreach($leads as $x):?><option value="<?=$x['id']?>"><?=e($x['contact_name']?:$x['name'])?></option><?php endforeach?></select></label><div class="fg" data-show="lead="><label>Name<input name="name"></label><label>Phone<input name="phone"></label><label class="full">Email<input name="email" type="email"></label></div><label>Title<input name="title" placeholder="<?=e(setting('appt_title'))?>"></label><label>Date &amp; time<input type="datetime-local" name="at" required></label><label>Notes<textarea name="notes" rows="2"></textarea></label><div class="md-f"><button class="btn btn-y"><?=icon('check')?>Book</button></div></form></div>
<?php if(isset($_GET['add'])):?><script>addEventListener('load',function(){A.modal('m-add')})</script><?php endif?>
